(() => {
  'use strict';
  const catalogue = window.DESIGN_SCREENS;
  const params = new URLSearchParams(location.search);
  const id = document.body.dataset.screen;
  const screen = catalogue.find(s => s.id === id);
  const names = {open:'Open',in_progress:'In progress',blocked:'Blocked',done:'Done',cancelled:'Cancelled'};
  const colors = {
    Blue:['#1d4ed8','#60a5fa'],Indigo:['#4338ca','#a5b4fc'],Purple:['#7e22ce','#c084fc'],Pink:['#be185d','#f9a8d4'],Red:['#b91c1c','#fca5a5'],Orange:['#c2410c','#fdba74'],Amber:['#92400e','#fcd34d'],Green:['#15803d','#86efac'],Teal:['#0f766e','#5eead4'],Slate:['#475569','#cbd5e1']
  };
  const items = [
    {key:'PLAN-24',title:'Add project permissions',state:'open',type:'Story',priority:'High',assignee:'Taylor',labels:['core','access']},
    {key:'PLAN-26',title:'Write the local startup guide',state:'open',type:'Task',priority:'Low',assignee:'Unassigned',labels:['docs']},
    {key:'PLAN-18',title:'Build the sprint board',state:'in_progress',type:'Story',priority:'High',assignee:'Taylor',labels:['core','ui']},
    {key:'PLAN-29',title:'Add item query filters',state:'in_progress',type:'Task',priority:'Medium',assignee:'agent-calm-otter-a31f',labels:['ui']},
    {key:'PLAN-21',title:'Add attachment previews',state:'blocked',type:'Task',priority:'Medium',assignee:'agent-calm-otter-a31f',labels:['files'],blocked_by_item_keys:['PLAN-24','PLAN-29']},
    {key:'PLAN-12',title:'Create the first administrator',state:'done',type:'Task',priority:'High',assignee:'Taylor',labels:['access']},
    {key:'PLAN-14',title:'Create and order sprints',state:'done',type:'Story',priority:'Medium',assignee:'Taylor',labels:['core']},
    {key:'PLAN-27',title:'Replace the old import flow',state:'cancelled',type:'Task',priority:'Low',assignee:'Unassigned',labels:['cleanup']}
  ];
  let state = params.get('state') || 'default';
  let mode = params.get('theme') || 'light';
  let accent = params.get('accent') || 'Blue';
  let fieldCount = 0;
  let toastTimer;
  let readinessPromptDismissed = false;
  const readOnly = () => state === 'read-only' || state === 'blockers-ready-readonly';
  const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const path = (target, variant='default', extra='') => `../${target}/index.html?state=${encodeURIComponent(variant)}&theme=${encodeURIComponent(mode)}&accent=${encodeURIComponent(accent)}${params.has('embed')?'&embed=1':''}${extra}`;
  const link = (label,target,cls='',variant='default',extra='') => `<a class="${cls}" href="${path(target,variant,extra)}">${label}</a>`;
  const btn = (label,action='',cls='') => `<button type="button" class="btn ${cls}" ${action}>${label}</button>`;
  const notice = label => `data-notice="${e(label)}"`;
  const status = s => `<span class="state ${s}">${names[s] || e(s)}</span>`;
  const itemType = value => { const type=String(value).toLowerCase(); const shape={story:'<path d="M5 3.5h10v13l-5-3.3-5 3.3z"/>',task:'<rect x="3" y="3" width="14" height="14" rx="2"/><path d="m6.2 10 2.5 2.5 5-5"/>',bug:'<path d="M7 6V5a3 3 0 0 1 6 0v1M7.5 2.8 6 1.5m6.5 1.3L14 1.5"/><rect x="6" y="6" width="8" height="11" rx="4"/><path d="M10 7v9M3 6l3 2m-4 3h4m-3 5 3-2m11-8-3 2m4 3h-4m3 5-3-2"/>'}[type];return `<span class="item-type-label"><svg class="item-type-icon type-${type}" width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${shape||''}</svg><span>${e(value)}</span></span>`;};
  const labels = list => list.map(x => `<span class="label">${e(x)}</span>`).join(' ');
  const avatar = (name='Taylor') => `<span class="avatar ${name.startsWith('agent')?'agent':''}" aria-hidden="true">${name==='Unassigned'?'–':name.startsWith('agent')?'A':'TR'}</span>`;
  const person = name => `<span class="row nowrap" style="gap:7px">${avatar(name)}<span>${name.startsWith('agent')?'calm-otter':e(name)}</span>${name.startsWith('agent')?'<span class="badge agent">Agent</span>':''}</span>`;
  const field = (name,value='',type='text',hint='',required=false) => {const k=`field-${++fieldCount}`;return `<label class="field" for="${k}"><span>${name}${required?' <span aria-hidden="true">*</span>':''}</span><input id="${k}" name="${k}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='password'?'autocomplete="new-password"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`;};
  const select = (name,options,selected='',hint='') => {const k=`field-${++fieldCount}`;return `<label class="field" for="${k}"><span>${name}</span><select id="${k}" data-field-label="${e(name)}">${options.map(x=>`<option ${x===selected?'selected':''}>${e(x)}</option>`).join('')}</select>${hint?`<span class="hint">${hint}</span>`:''}</label>`;};
  const textarea = (name,value='',hint='') => {const k=`field-${++fieldCount}`;return `<label class="field" for="${k}"><span>${name}</span><textarea id="${k}" rows="4">${e(value)}</textarea>${hint?`<span class="hint">${hint}</span>`:''}</label>`;};
  const error = text => `<div class="form-error" role="alert">${text}</div>`;
  const pageHead = (title,subtitle='',actions='') => `<div class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="row">${actions}</div></div>`;
  const section = (title,body,action='') => `<section class="section"><div class="section-head"><h2>${title}</h2>${action}</div>${body}</section>`;
  const empty = (title,desc,actions='',symbol='□') => `<div class="empty"><div class="empty-mark" aria-hidden="true">${symbol}</div><h2>${title}</h2><p class="muted">${desc}</p><div class="row">${actions}</div></div>`;
  const table = (data=items,checkbox=false,full=false) => `<div class="panel flush"><div class="table-wrap"><table class="table"><thead><tr>${checkbox?'<th><input type="checkbox" aria-label="Select all visible items"></th>':''}<th>Key</th><th>Title</th><th>Type</th><th>State</th><th>Priority</th><th>Assignee</th>${full?'<th>Sprint</th><th>Labels</th><th>Updated</th>':''}</tr></thead><tbody>${data.map(i=>`<tr>${checkbox?`<td><input type="checkbox" aria-label="Select ${i.key}" ${state==='selected'?'checked':''}></td>`:''}<td class="key">${i.key}</td><td class="title-cell">${link(e(i.title),'08-item-detail','item-title',i.state==='blocked'?(dependenciesReady()?'blockers-ready':'blocked'):'default',`&item=${i.key}`)}${blockerIndicator(i)}</td><td>${itemType(i.type)}</td><td>${status(i.state)}</td><td><span class="priority ${i.priority.toLowerCase()}">${i.priority}</span></td><td>${person(i.assignee)}</td>${full?`<td class="nowrap">Core workflow</td><td>${labels(i.labels)}</td><td class="small nowrap">5 min ago</td>`:''}</tr>`).join('')}</tbody></table></div><div class="footer-row"><span>${data.length} items · page 1 of 1</span><div class="row"><button class="btn small" disabled>Previous</button><button class="btn small" disabled>Next</button></div></div></div>`;
  const countStrip = () => `<div class="summary-strip"><span><strong>8</strong>In this sprint</span><span><strong>5</strong>Unfinished</span><span><strong>2</strong>Done</span><span><strong>1</strong>Cancelled</span></div>`;
  const dependenciesReady = () => ['blockers-ready','blockers-ready-readonly'].includes(state);
  const blockerIndicator = i => i.state==='blocked'?`<span class="dependency-pill">2 blockers${dependenciesReady()?' · 2 Done':''}</span>${dependenciesReady()?'<span class="ready-label">✓ Ready to resume</span>':''}`:'';
  function readyBanner(){return `<div class="dependency-banner" role="status"><div><strong>All blockers are Done</strong><p>This item is still Blocked.${readOnly()?' You do not have permission to change its state.':' Move it to In progress when you are ready.'}</p></div>${readOnly()?'<span class="small muted">Read-only</span>':btn('Move to In progress','data-show-ready','primary small')}</div>`;}
  function dependencyPanel(current){
    if(current.state!=='blocked'&&!['PLAN-24','PLAN-29'].includes(current.key)&&state!=='blockers-removed')return '';
    const targets=current.state==='blocked'?(dependenciesReady()?[items[5],items[6]]:params.get('blocker_keys')?params.get('blocker_keys').split(',').map(k=>items.find(i=>i.key===k)).filter(Boolean):params.get('blocker_count')==='1'?[items[3]]:[items[0],items[3]]):[];
    const blockedBy=targets.length?targets.map(i=>`<div class="dependency-row"><div class="grow"><span class="key">${i.key}</span> <strong>${e(i.title)}</strong><div class="row" style="margin-top:6px">${status(i.state)}<span class="small muted">Sprint 1 · Core workflow</span></div></div>${readOnly()?'':link('Remove','26-delete-confirmation','small',targets.length===1?'unlink-last-blocker':'unlink-blocker')}</div>`).join(''):'<p class="small muted">No blockers linked.</p>';
    const blocks=['PLAN-24','PLAN-29'].includes(current.key)?`<div class="dependency-row"><div class="grow">${link('PLAN-21 · Add attachment previews','08-item-detail','','blocked')}<div class="small muted">Blocked · 2 blockers</div></div></div>`:'<p class="small muted">No items depend on this item.</p>';
    return section('Dependencies',`<div class="panel"><div class="section-head"><h3>Blocked by <span class="count">${targets.length}</span></h3>${readOnly()?'':link('+ Add blocker','19-item-link','small','blocked-by')}</div>${blockedBy}<div class="section-head" style="margin-top:20px"><h3>Blocks <span class="count">${['PLAN-24','PLAN-29'].includes(current.key)?1:0}</span></h3></div>${blocks}</div>`);
  }
  function readyDialogSpec(){
    const readonly=state==='read-only';
    return {title:'All blockers are Done',subtitle:'PLAN-21 · Add attachment previews',body:`<div class="stack">${state==='conflict'?error('A blocker changed after this prompt opened. Refresh the dependency list before continuing.'):''}<p>Move this item from Blocked to In progress?</p><div class="quiet-band"><div class="dependency-row"><span class="grow"><span class="key">PLAN-12</span> Create the first administrator</span>${status('done')}</div><div class="dependency-row"><span class="grow"><span class="key">PLAN-14</span> Create and order sprints</span>${status('done')}</div></div><p class="small muted">${readonly?'You can view this item but cannot change its state.':'Not now keeps the item Blocked. You will be asked again the next time you open it.'}</p><p class="small muted">There are still 2 Blocked by links. If all links are removed instead, the item moves to Open automatically.</p></div>`,foot:btn('Not now','data-dismiss-ready','ghost')+(readonly?'<button class="btn primary" disabled>Move to In progress</button>':state==='conflict'?link('Refresh dependencies','34-blockers-resolved','btn primary'):btn('Move to In progress','data-resume-preview','primary'))};
  }
  function showReadyDialog(){
    if(document.querySelector('.overlay'))return;
    const spec=readyDialogSpec();
    const layer=document.createElement('div');layer.className='overlay readiness-overlay';
    layer.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="ready-title"><div class="modal-head"><div><h1 id="ready-title">${spec.title}</h1><p class="modal-subtitle">${spec.subtitle}</p></div>${btn('×','data-dismiss-ready aria-label="Close readiness prompt"','ghost icon-btn')}</div><div class="modal-content">${spec.body}</div><footer class="modal-footer">${spec.foot}</footer></section>`;
    document.querySelector('.app').inert=true;document.getElementById('preview-root').append(layer);
    layer.querySelectorAll('[data-dismiss-ready]').forEach(b=>b.addEventListener('click',dismissReady));
    layer.querySelector('[data-resume-preview]')?.addEventListener('click',resumePreview);
    layer.querySelector('button')?.focus({preventScroll:true});
  }
  function dismissReady(){readinessPromptDismissed=true;document.querySelector('.overlay')?.remove();document.querySelector('.app').inert=false;document.querySelector('[data-show-ready]')?.focus({preventScroll:true});}
  function resumePreview(){state='resumed';readinessPromptDismissed=true;if(id==='34-blockers-resolved'){location.href=path('08-item-detail','resumed','&item=PLAN-21');return;}changeQuery();render();toast('Moved to In progress in this preview.');}
  function applyTheme(){
    const dark = mode==='dark' || (mode==='system' && matchMedia('(prefers-color-scheme: dark)').matches);
    document.documentElement.dataset.theme=dark?'dark':'light';
    const c=colors[accent] || colors.Blue;
    document.documentElement.style.setProperty('--accent',c[dark?1:0]);
    document.documentElement.style.setProperty('--accent-soft',`color-mix(in srgb, ${c[dark?1:0]} ${dark?'12':'8'}%, ${dark?'#151c28':'#ffffff'})`);
  }
  function shell(content,active='Home',inert=false){
    const nav = [['Home','03-home','⌂'],['Project overview','04-project-overview','▧'],['Planning','05-planning','☷'],['List','06-item-list','≡'],['Sprint','07-sprint-board','▥']];
    return `<div class="app" ${inert?'inert':''}><aside class="sidebar"><a class="brand" href="${path('03-home')}"><span class="brand-mark" aria-hidden="true">✓</span>Local Planner</a><div><div class="nav-label">Workspace</div>${btn('Local Planner <span class="muted">⌄</span>','data-project-picker','project-switch full')}</div><nav class="nav-group" aria-label="Main navigation">${nav.map(([n,target,symbol])=>link(`<span class="nav-symbol" aria-hidden="true">${symbol}</span>${n}`,target,`nav-link ${active===n?'active':''}`)).join('')}</nav>${!readOnly()?`<div class="nav-group"><div class="nav-label">Administration</div>${link('<span class="nav-symbol" aria-hidden="true">♙</span>Users','09-users',`nav-link ${active==='Users'?'active':''}`)}${link('<span class="nav-symbol" aria-hidden="true">⚿</span>Permissions','10-project-permissions',`nav-link ${active==='Permissions'?'active':''}`)}</div>`:''}<div class="sidebar-bottom"><div class="nav-group">${link('Appearance','11-appearance',`nav-link ${active==='Appearance'?'active':''}`)}${link('Account','12-account-security',`nav-link ${active==='Account'?'active':''}`)}</div><div class="account">${avatar()}<div><strong class="small">Taylor Ramos</strong><div class="muted small">${readOnly()?'Project viewer':'Administrator'}</div></div></div></div></aside><div class="app-main"><header class="header"><div class="row">${btn('☰','data-menu aria-label="Open navigation"','ghost mobile-menu')}<div class="breadcrumb">${active==='Home'?'Workspace':`Local Planner <span aria-hidden="true">/</span> <strong>${active}</strong>`}</div></div><div class="row header-account">${btn('◐','data-theme-toggle aria-label="Toggle light and dark appearance"','ghost icon-btn')}${avatar()}</div></header><main class="page">${content}</main></div></div>`;
  }
  function home(){
    if(state==='empty'||state==='no-access') return pageHead('Home','Your projects and the work that needs you.')+empty(state==='no-access'?'No projects shared with you':'Start with a project',state==='no-access'?'An administrator can give you access to a project.':'Keep project context, work and sprints together in one place.',state==='empty'?link('Create project','13-project-editor','btn primary'):'');
    const projects=[['LP','Local Planner','PLAN','Sprint 1 · Core workflow','5 unfinished','2 done · 1 cancelled'],['RL','Reading List','READ','Sprint 3 · List cleanup','3 unfinished','4 done · 0 cancelled'],['HL','Home lab','LAB','No active sprint','Backlog · 6 items','']];
    return pageHead('Home','A clear view of your projects and current work.',readOnly()?'':link('+ New project','13-project-editor','btn primary'))+`<div class="section-head"><h2>Projects <span class="count">3</span></h2></div><div class="panel flush">${projects.map(([initial,name,key,sprint,work,done])=>`<div class="project-row"><div class="row"><span class="project-key">${initial}</span><div>${link(name,'04-project-overview','project-name')}<div class="key">${key}</div></div></div><div>${link(sprint,sprint==='No active sprint'?'05-planning':'07-sprint-board')}<div class="small muted">${work}</div></div><div class="mini-stats">${done}</div>${link('Open →','04-project-overview','small')}</div>`).join('')}</div>`+(dependenciesReady()?section('Ready to resume',table([items[4]])): '')+section('Assigned to you',table(items.filter(i=>i.assignee==='Taylor'&&!['done','cancelled'].includes(i.state))),link('View all items →','06-item-list','small'));
  }
  function project(){
    const title=pageHead('Local Planner','PLAN · A lightweight home for projects, sprints and agent work.',readOnly()?'':link('Edit project','13-project-editor','btn','edit'));
    const tabs=`<div class="tabs">${link('Overview','04-project-overview',`tab ${state!=='activity'?'active':''}`)}${link('Activity','04-project-overview',`tab ${state==='activity'?'active':''}`,'activity')}</div>`;
    if(state==='activity')return title+tabs+`<div class="panel"><h2>Project activity</h2>${activity()}</div>`;
    return title+tabs+`<div class="panel"><div class="section-head"><h2>About this project</h2></div><p class="prose">Build a small, local planning tool that makes the next piece of work clear. Keep context with each item and let human and agent users work from the same project.</p><div class="row" style="margin-top:20px">${link('Open Planning','05-planning','btn primary')}${link('View items','06-item-list','btn')}${!readOnly()?link('Manage permissions','10-project-permissions','btn ghost'):''}</div></div>`+section('Current sprint',state==='empty'?empty('No active sprint','Create or start a sprint from Planning.',link('Open Planning','05-planning','btn')):`<div class="panel"><div class="between"><div><span class="badge">Active</span><h2 style="margin-top:9px">Sprint 1 · Core workflow</h2><p class="small muted" style="margin-top:5px">Started Nov 9, 2026</p></div>${link('Open sprint →','07-sprint-board','btn')}</div>${countStrip()}</div>`)+section('Upcoming sprints',`<div class="panel"><div class="between"><div><strong>Sprint 2 · Collaboration</strong><div class="small muted">Not started · 2 items</div></div>${link('Plan work →','05-planning','small')}</div></div>`);
  }
  function planning(){
    const selected=['selected','read-only','blockers-ready'].includes(state);
    const head=pageHead(selected?'Sprint 1 · Core workflow':'Planning',selected?'Active · Ordered sprint work':'Choose a sprint to plan its work.',selected?link('Overview','07-sprint-board','btn','overview')+link('Board','07-sprint-board','btn')+(readOnly()?'':link('Edit sprint','14-sprint-editor','btn','rename')):link('+ New sprint','14-sprint-editor','btn primary'))+`<section class="planning-active-sprint" aria-label="Active sprint"><div class="planning-active-context"><span class="planning-active-label">Active sprint</span><h2>Sprint 3 · Current work</h2><p class="small muted">8 items · 2 Done · Started Nov 9, 2026</p></div><div class="row planning-active-actions">${link('Plan active sprint','05-planning','btn primary small','selected')}${link('Board','07-sprint-board','btn small')}${link('Overview','07-sprint-board','btn small','overview')}${readOnly()?'':link('Close sprint','16-sprint-close','btn small')}</div></section>`;
    if(state==='empty')return head+empty('No sprints yet','Create a sprint to group the next work.',link('Create sprint','14-sprint-editor','btn primary'));
    if(!selected){
      const stage=params.get('sprint_state')==='closed'?'closed':'planned';
      const data=stage==='closed'?['Sprint 1 · Completed foundation','Sprint 2 · Completed collaboration']:stage==='active'?['Sprint 3 · Current work']:['Sprint 4 · Next improvements','Sprint 5 · Future polish'];
      const tabs=`<nav class="tabs" aria-label="Sprint status">${[['planned','Not started',2],['closed','Closed',2]].map(([key,title,count])=>link(`${title} <span class="count">${count}</span>`,'05-planning','tab '+(stage===key?'active':''),'default','&sprint_state='+key)).join('')}</nav>`;
      return head+tabs+`<div class="stack">${data.map((name,n)=>`<article class="panel between"><div><div class="row"><span class="key">${n+1}</span><h2>${name}</h2><span class="badge">${stage==='planned'?'Not started':stage==='active'?'Active':'Closed'}</span></div><p class="muted" style="margin:10px 0">${stage==='planned'?'Upcoming work to plan.':'Sprint context and historical work.'}</p><div class="small muted">${stage==='active'?'8 items · 2 Done · 1 Cancelled':'0 items'}</div></div><div class="row">${link(stage==='closed'?'View plan':'Plan sprint','05-planning','btn primary','selected')}${link('View sprint','07-sprint-board','btn','overview')}${link('Edit','14-sprint-editor','btn ghost','rename')}</div></article>`).join('')}</div>`;
    }
    const rows=items.slice(0,4).map(i=>`<div class="between" style="padding:15px 20px;border-top:1px solid var(--line);gap:18px"><span class="muted" aria-hidden="true">⠿</span><span class="key">${i.key}</span><div class="grow">${link(e(i.title),'08-item-detail','item-title')}${blockerIndicator(i)}</div>${status(i.state)}${readOnly()?'':btn('↑',notice('Move this item earlier in the complete sprint order.'),'small ghost')+btn('↓',notice('Move this item later in the complete sprint order.'),'small ghost')}</div>`).join('');
    return head+link('← All sprints','05-planning','btn ghost')+`<section class="sprint-section section"><div class="sprint-section-head"><div><h2>Sprint items <span class="count">4</span></h2><p class="small muted">Drag rows to reorder. Add Backlog items below.</p></div>${readOnly()?'':link('+ Create item','17-item-create','btn small')}</div>${rows}<div class="sprint-drop" style="padding:25px">${readOnly()?'Items in planned order':'Drop Backlog items here · Items append, then drag to reorder'}</div></section><section class="panel section"><div class="section-head"><h2>Backlog <span class="count">3</span></h2>${readOnly()?'':link('+ Create backlog item','17-item-create','btn small','backlog')}</div><div class="two-fields" style="margin-bottom:20px">${field('Search backlog','','search','Search title, description or key')}${select('Type',['All types','Story','Task','Bug'])}${select('State',['All states',...Object.values(names)])}${select('Priority',['All priorities','None','Low','Medium','High','Urgent'])}${select('Assignee',['Anyone','Taylor','Unassigned'])}${select('Label',['All labels','core','ui'])}</div>${[['PLAN-31','Add keyboard shortcuts'],['PLAN-32','Document file previews'],['PLAN-33','Review the default labels']].map(([key,title])=>`<div class="planning-item between"><span class="muted">⠿</span><span class="key">${key}</span><strong class="grow">${title}</strong>${status('open')}${readOnly()?'':`<span class="row">${btn('⇈',notice('Move this item to the top of the entire Backlog, including hidden items.'),'small ghost')}${btn('↑',notice('Move before the previous matching Backlog item; hidden items keep relative order.'),'small ghost')}${btn('↓',notice('Move after the next matching Backlog item, including across pages.'),'small ghost')}${btn('Add to sprint ↑',notice('Move this Backlog item into the selected sprint without changing state.'),'small')}</span>`}</div>`).join('')}</section>`;
  }
  function list(){
    const head=pageHead('Items','Find work across the projects you can access.',readOnly()?'':link('+ Create item','17-item-create','btn primary'));
    const filters=`<div class="filters"><input class="filter-input" aria-label="Search items" placeholder="Search title, key or description"><button class="filter-chip selected" data-notice="Project selection stays in the list query URL.">Project: Local Planner ⌄</button>${link('Sprint: Core workflow ⌄','06-item-list','filter-chip','filters')}${link('State ⌄','06-item-list','filter-chip','filters')}${link('+ Filter','06-item-list','filter-chip','filters')}${btn('Columns',notice('Default columns: Key, Title, Type, State, Sprint, Priority, Assignee, Labels, Updated.'),'ghost small')}</div>`;
    const builder=state==='filters'?`<div class="panel stack" style="margin-bottom:18px"><h2>Filter items</h2><div class="two-fields">${select('Sprint',['Any sprint','Sprint 1 · Core workflow','Sprint 2 · Collaboration','Backlog'])}${select('Type',['Any type','Story','Task','Bug'])}${select('State',['Any state',...Object.values(names)])}${select('Assignee',['Anyone','Taylor','agent-calm-otter-a31f','Unassigned'])}${select('Priority',['Any priority','None','Low','Medium','High','Urgent'])}${select('Labels',['Any labels','core','ui','files','access'])}${field('Updated since','','date')}</div><p class="small muted">Match all filter groups and all selected labels. Values within one other filter match any selected value.</p><div class="row">${link('Apply filters','06-item-list','btn primary')}${link('Clear all','06-item-list','btn ghost')}</div></div>`:'';
    return head+filters+builder+(state==='empty'?empty('No items match these filters','Try another state or sprint, or clear the filters.',link('Clear filters','06-item-list','btn')):table(items,true,true));
  }
  function board(){
    const closed=state==='closed', planned=state==='planned';
    const lifecycle=closed?'Closed':planned?'Not started':'Active';
    const head=pageHead(planned?'Sprint 2 · Collaboration':'Sprint 1 · Core workflow',`${lifecycle}${planned?'':' · Started Nov 9, 2026'}${closed?' · Closed Nov 9, 2026':''}`,`${link('Choose sprint ⌄','05-planning','btn')}${readOnly()||closed?'':link(planned?'Start sprint':'Close sprint',planned?'15-sprint-start':'16-sprint-close','btn primary')}`);
    if(state==='overview')return head+`<nav class="tabs">${link('Overview','07-sprint-board','tab active','overview')}${link('Board','07-sprint-board','tab')}</nav><section class="panel section"><div class="section-head"><h2>Description</h2>${link('Edit description','14-sprint-editor','btn small','rename')}</div><h3>Sprint goal</h3><p class="prose" style="margin-top:12px">Make the core planning workflow reliable and easy to use. Organize upcoming work, keep context with each item and share progress with local agents.</p></section><section class="panel section"><h2>Item overview</h2><div class="row" style="margin-top:20px">${Object.keys(names).map(k=>`<div class="panel grow">${status(k)}<h2 style="margin-top:12px">${items.filter(i=>i.state===k).length}</h2></div>`).join('')}</div><p class="small muted" style="margin-top:20px">Done and Cancelled items count toward sprint closure.</p></section>`;
    if(state==='empty')return head+empty('This sprint has no items','Move work from Backlog or create an item for this sprint.',readOnly()?'':link('Open Planning','05-planning','btn primary'));
    const data=closed?items.filter(i=>['done','cancelled'].includes(i.state)):planned?[{key:'PLAN-30',title:'Add user management',state:'open',type:'Story',priority:'Medium',assignee:'Taylor',labels:['access']},{key:'PLAN-34',title:'Refine item comments',state:'open',type:'Task',priority:'Low',assignee:'Unassigned',labels:['ui']}]:items;
    return head+`<nav class="tabs">${link('Overview','07-sprint-board','tab','overview')}${link('Board','07-sprint-board','tab active')}</nav>`+(closed?`<div class="callout" style="margin-bottom:22px">This sprint is closed. Its remaining items are Done or Cancelled. Move an item out before reopening it.</div>`:'')+`<div class="between" style="margin-bottom:18px"><span class="small muted">${data.length} items · ${closed?'2 done · 1 cancelled':planned?'2 unfinished · 0 done · 0 cancelled':'5 unfinished · 2 done · 1 cancelled'}</span>${readOnly()||closed?'':link('+ Create item','17-item-create','btn small')}</div><div class="board-scroll"><div class="board">${Object.keys(names).map(s=>{const arr=data.filter(i=>i.state===s);return `<section class="lane" aria-label="${names[s]}"><div class="lane-head">${status(s)}<span class="count">${arr.length}</span></div>${arr.map(i=>`<a class="work-card" href="${path('08-item-detail',closed?'closed-sprint':i.state==='blocked'?(dependenciesReady()?'blockers-ready':'blocked'):'default',`&item=${i.key}`)}"><div class="between"><span class="key">${i.key}</span>${itemType(i.type)}</div><h3>${e(i.title)}</h3><div class="row" style="gap:4px">${labels(i.labels)}</div>${blockerIndicator(i)}<div class="card-foot"><span class="priority ${i.priority.toLowerCase()}">${i.priority}</span>${avatar(i.assignee)}</div></a>`).join('')}${!readOnly()&&!closed?link('+ Add item','17-item-create','lane-add'):''}</section>`;}).join('')}</div></div>`;
  }
  function activity(){return [['Taylor','updated the priority of PLAN-18 to High','5 minutes ago'],['agent-calm-otter-a31f','moved PLAN-29 to In progress','12 minutes ago'],['Taylor','started Sprint 1 · Core workflow','Today at 9:14 AM']].map(([who,what,when])=>`<div class="activity-row"><span class="activity-dot" aria-hidden="true"></span><div><strong>${e(who)}</strong> ${what}<div class="small muted">${when}${who.startsWith('agent')?' · Agent':''}</div></div></div>`).join('');}
  function item(){
    const dependencyVariant=['blocked','blockers-ready','blockers-ready-readonly','blockers-removed','resumed'].includes(state);
    const selected=items.find(i=>i.key===params.get('item'))||(dependencyVariant?items[4]:items[2]);
    const current={...selected,state:state==='blockers-removed'?'open':state==='resumed'?'in_progress':dependencyVariant?'blocked':selected.state};
    const closed=state==='closed-sprint';
    const description=`<p>Make the current sprint easy to understand at a glance. Show every item in its current state and keep the next action close to the work.</p><ul><li>Show Open, In progress, Blocked, Done and Cancelled columns.</li><li>Keep item type, priority, assignee and labels visible on cards.</li><li>Provide a menu alternative to dragging a card.</li></ul>`;
    const editing=state==='editing';
    const editableProp=(name,value,target='18-item-move')=>`<div class="detail-prop"><label>${name}</label>${readOnly()?`<span>${value}</span>`:name==='Sprint'||(name==='State'&&closed)?link(`${value} <span class="muted">⌄</span>`,'18-item-move','btn ghost',closed?'reopen':'single'):btn(`${value} <span class="muted">⌄</span>`,`data-property="${name}"`,'ghost')}</div>`;
    const main=`${dependenciesReady()?readyBanner():state==='blockers-removed'?'<div class="callout" role="status" style="margin-bottom:22px"><strong>All blockers removed — moved to Open</strong><p class="small">The final Blocked by link was removed. This item was reopened automatically.</p></div>':state==='resumed'?'<div class="callout" role="status" style="margin-bottom:22px">Moved to In progress. The completed dependency links remain for context.</div>':''}${closed?'<div class="callout" style="margin-bottom:24px">This item belongs to a closed sprint. Move it to Backlog or another sprint to change its state.</div>':''}<section><div class="section-head"><h2>Description</h2>${readOnly()?'':link(editing?'Cancel':'Edit','08-item-detail','small',editing?'default':'editing')}</div>${editing?`<div class="stack">${textarea('Description','Make the current sprint easy to understand at a glance.\n\n- Show the five item states.\n- Keep standard card properties visible.','Markdown supported.')}<div class="row">${btn('Save description','data-save-preview','primary')}${link('Cancel','08-item-detail','btn ghost')}</div></div>`:`<div class="prose">${description}</div>`}</section>${dependencyPanel(current)}${section('Linked items',`<div class="quiet-band"><div class="between"><span><span class="badge">Child of</span> <span class="key">PLAN-7</span> &nbsp; Core planning workflow</span><span class="small muted">Backlog</span></div><div class="between" style="margin-top:13px"><span><span class="badge">Related</span> <span class="key">PLAN-29</span> &nbsp; Add item query filters</span>${status('in_progress')}</div></div>`,readOnly()?'':link('+ Link item','19-item-link','small'))}${section('Attachments',`<div class="row"><a class="attachment-tile" href="${path('21-attachment-preview')}"><div class="file-glyph">PNG</div><strong class="small">board-reference.png</strong><div class="small muted">144 KB · Taylor</div></a><a class="attachment-tile" href="${path('21-attachment-preview','text')}"><div class="file-glyph">MD</div><strong class="small">acceptance-notes.md</strong><div class="small muted">2 KB · calm-otter</div></a></div>${state==='uploading'?'<div class="quiet-band" role="status" style="margin-top:12px">Uploading sprint-notes.txt… 68% <progress value="68" max="100" aria-label="Upload progress"></progress></div>':''}`,readOnly()?'':btn('↑ Upload file',notice('Upload preview: choose a file up to 25 MiB. File access follows project attachment permissions.'),'ghost small'))}<section class="section"><div class="tabs">${link('Comments','08-item-detail',`tab ${state!=='activity'?'active':''}`)}${link('Activity','08-item-detail',`tab ${state==='activity'?'active':''}`,'activity')}</div>${state==='activity'?activity():`<div class="comment">${avatar()}<div class="comment-body"><div class="comment-meta"><strong>Taylor</strong> · 20 minutes ago</div><p>The cancelled lane should stay separate from Done so the outcome is clear.</p>${readOnly()?'':`<div class="row" style="margin-top:6px">${btn('Edit',notice('Comment editing replaces this comment body with an inline editor.'),'ghost small')}${link('Delete','26-delete-confirmation','small danger-text','comment')}</div>`}</div></div><div class="comment">${avatar('agent-calm-otter-a31f')}<div class="comment-body"><div class="comment-meta"><strong>agent-calm-otter-a31f</strong> <span class="badge agent">Agent</span> · 8 minutes ago</div><p>I added the card fields and keyboard interaction notes.</p></div></div>${readOnly()?'':`<div class="stack"><textarea class="comment-compose" aria-label="Add a comment" placeholder="Add context or an update…"></textarea><div>${btn('Add comment',notice('Comment added in this preview only.'),'primary')}</div></div>`}`}</section>`;
    return `<div class="eyebrow">${link('Items','06-item-list')} <span aria-hidden="true">/</span> ${current.key} ${itemType(current.type)}</div>`+pageHead(e(current.title),'',readOnly()?'':btn('•••','data-item-menu aria-label="More item actions"','ghost'))+`<div class="detail-grid"><div>${main}</div><aside class="detail-side">${editableProp('State',status(closed?'done':current.state),closed?'18-item-move':'07-sprint-board')}${editableProp('Type',itemType(current.type),'17-item-create')}${editableProp('Sprint',closed?'Sprint 0 · Foundation':'Sprint 1 · Core workflow')}${editableProp('Assignee',person(current.assignee),'17-item-create')}${editableProp('Priority',current.priority,'17-item-create')}<div class="detail-prop"><label>Labels</label><div class="row">${labels(current.labels)}</div>${readOnly()?'':link('Manage labels','20-label-manager','small')}</div><div class="small muted">Created Nov 8, 2026<br>Updated 5 minutes ago<br>Reported by Taylor</div></aside></div>`;
  }
  function users(){
    const head=pageHead('Users','Human and agent accounts. Project access is granted separately.',link('+ Create user','22-user-editor','btn primary'));
    if(state==='empty')return head+empty('No users match these filters','Try another account type or enabled state.',link('Clear filters','09-users','btn'));
    return head+`<div class="filters">${btn('Kind: All ⌄',notice('Filter Human or Agent accounts.'))}${btn('Status: Enabled ⌄',notice('Filter Enabled or Disabled accounts.'))}</div><div class="panel flush table-wrap"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Type</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${[['Taylor Ramos','tramos','Human','Administrator','human'],['Calm Otter','agent-calm-otter-a31f','Agent','User','default'],['Morgan Lee','morgan','Human','User','human']].map(([name,user,kind,role,v])=>`<tr><td><div class="row">${avatar(user)}<strong>${name}</strong></div></td><td class="mono small">${user}</td><td><span class="badge ${kind==='Agent'?'agent':''}">${kind}</span></td><td>${role}</td><td><span class="success-text">Enabled</span></td><td>${link('Details →','23-user-detail','small',v)}</td></tr>`).join('')}</tbody></table></div>`;
  }
  function permissions(){
    const no=state==='no-grants',admin=state==='admin-user';
    const rows=[['Project',[true,false,false,false]],['Sprints',[true,true,true,false]],['Items',[true,true,true,false]],['Comments',[true,true,true,false]],['Attachments',[true,true,false,false]]];
    return pageHead('Project permissions','Choose a user, then grant only the project access they need.')+`<div class="permission-layout"><aside class="panel"><h3 style="margin-bottom:12px">Users</h3>${[['Calm Otter','Agent',!admin],['Morgan Lee','Human',false],['Taylor Ramos','Administrator',admin]].map(([n,k,selected])=>`<button class="user-choice ${selected?'selected':''}" data-notice="Choose the No grants or Admin user state above to review other permission scenarios."><strong>${n}</strong><div class="small muted">${k}</div></button>`).join('')}</aside><section class="panel"><div class="section-head"><div><h2>${admin?'Taylor Ramos':'Calm Otter'} <span class="badge ${admin?'':'agent'}">${admin?'Administrator':'Agent'}</span></h2><p class="small muted">${admin?'tramos':'agent-calm-otter-a31f'}</p></div></div>${state==='conflict'?error('Project access changed since this draft was opened. Review the latest permissions before saving.'):''}<div class="callout" style="margin-bottom:18px">${admin?'Administrators have full installation access. Explicit project grants do not restrict that access.':no?'This user has no access to this project until you grant it.':'Project view is required. Write permissions also require View for that resource.'}</div><div class="table-wrap"><table class="table permission-table"><thead><tr><th>Resource</th><th>View</th><th>Create</th><th>Update</th><th>Delete</th></tr></thead><tbody>${rows.map(([resource,grants])=>`<tr><th>${resource}</th>${grants.map((yes,k)=>`<td>${resource==='Project'&&[1,3].includes(k)?'<span class="small muted">Admin only</span>':`<input type="checkbox" aria-label="${resource} ${['View','Create','Update','Delete'][k]}" ${admin?'checked disabled':yes&&!no?'checked':''}>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${state==='dirty'?'<p class="small" role="status" style="margin-top:16px">Unsaved permission changes</p>':''}<p class="small muted" style="margin-top:16px">Comments and attachments also require item visibility. New users start with no project access.</p><div class="between" style="margin-top:24px"><div>${admin?'':link('Revoke project access','26-delete-confirmation','small danger-text','blocked')}</div><div class="row">${btn('Discard changes',notice('Permission draft discarded.'),'ghost')}${btn('Save permissions',admin?'disabled':'data-save-permissions','primary')}</div></div></section></div>`;
  }
  function appearance(){
    return pageHead('Appearance','Choose the look that feels comfortable. Your preference follows your account.')+`<section><div class="section-head"><h2>Mode</h2><span class="small ${state==='error'?'danger-text':'muted'}" role="status">${state==='saving'?'Saving…':state==='error'?'Could not save. Try again.':'Saved'}</span></div><div class="mode-grid">${['Light','Dark','System'].map(n=>`<button class="mode-choice ${mode===n.toLowerCase()?'selected':''}" data-mode="${n.toLowerCase()}" aria-pressed="${mode===n.toLowerCase()}"><div class="mini-window ${n.toLowerCase()}" aria-hidden="true"><span></span></div>${n}</button>`).join('')}</div><p class="small muted" style="margin-top:12px">System follows your device's appearance.</p></section>${section('Accent color',`<div class="swatches">${Object.entries(colors).map(([n,c])=>`<button class="swatch" data-accent="${n}" aria-pressed="${accent===n}"><span class="swatch-dot" style="--swatch:${c[mode==='dark'?1:0]}" aria-hidden="true"></span>${n}</button>`).join('')}</div>`)}<div class="panel theme-example"><div class="section-head"><h3>Preview</h3><span class="label">core</span></div><div class="row" style="margin-bottom:17px">${status('open')}${status('in_progress')}${status('blocked')}${status('done')}${status('cancelled')}</div>${btn('Primary action',notice('Accent colors change actions and selection, not the meaning of item states.'),'primary')} ${btn('Secondary action',notice('Theme preview only.'))}</div>`;
  }
  function account(){return pageHead('Account','Your identity and sign-in settings.')+`<div class="stack" style="max-width:720px"><section class="panel"><h2>Signed in as Taylor Ramos</h2><div class="row" style="margin-top:16px">${avatar()}<div><strong>tramos</strong><div class="small muted">Human · Administrator</div></div></div></section><section class="panel"><div class="between"><div><h2>Password</h2><p class="muted small" style="margin-top:7px">Changing your password signs out existing sessions.</p></div>${link('Change password','25-password-editor','btn')}</div></section><section class="panel"><div class="between"><div><h2>Sign out</h2><p class="muted small" style="margin-top:7px">End this browser session.</p></div>${link('Sign out','02-login','btn')}</div></section></div>`;}
  function auth(setup){
    if(state==='already-initialized')return `<div class="auth-page"><div class="auth-card">${empty('Setup is already complete','Sign in with an existing account.',link('Go to sign in','02-login','btn primary'))}</div></div>`;
    return `<main class="auth-page"><div class="auth-card"><div class="brand auth-brand"><span class="brand-mark" aria-hidden="true">✓</span>Local Planner</div><h1>${setup?'Create your administrator':'Welcome back'}</h1><p class="muted" style="margin-top:10px">${setup?'Start your local workspace with a username and password.':'Sign in to your local workspace.'}</p><form class="panel stack" data-auth-form="${setup?'setup':'login'}">${state==='validation'?error(setup?'Please correct the fields below.':'The username or password is incorrect.'):''}${field('Username',setup?'':'tramos','text',setup?'Use a name you will recognize.':'',true)}${field('Password','','password',setup?'Use at least 12 characters.':'',true)}${setup?field('Confirm password','','password','',true):''}<label class="check small"><input type="checkbox" data-show-password>Show password</label><button class="btn primary full" ${state==='submitting'?'disabled':''}>${state==='submitting'?(setup?'Creating administrator…':'Signing in…'):(setup?'Create administrator':'Sign in')}</button></form><p class="auth-footer">${setup?'This account manages users and project access.':'Runs locally. Your projects stay on this installation.'}</p><div class="row" style="justify-content:center;margin-top:15px">${btn('◐ Appearance','data-theme-toggle','ghost small')}</div></div></main>`;
  }
  const footer=(primary='Save',target='',variant='default',danger=false)=>`${link('Cancel',screen.parent||'03-home','btn ghost')}${target?link(primary,target,`btn ${danger?'danger':'primary'}`,variant):btn(state==='submitting'?'Saving…':primary,state==='submitting'?'disabled':'data-save-preview',danger?'danger':'primary')}`;
  function dialogContent(){
    const commonError=state==='validation'?error('Check the highlighted values before continuing.'):'';
    switch(id){
      case '33-block-item':return {title:'Move item to Blocked',subtitle:'PLAN-18 · Build the sprint board',wide:true,body:`<div class="stack">${state==='validation'?error('Choose at least one Blocked by item before continuing.'):state==='conflict'?error('A selected item changed or was cancelled. Refresh the available blockers.'):''}<p>${state==='existing-blockers'?'Existing Blocked by links can satisfy this requirement.':'Choose the items that are blocking this work.'} You can select more than one.</p>${field('Find blockers','permissions','search','Visible items in Local Planner. Cancelled items cannot be blockers.')}<div class="quiet-band"><label class="dependency-row"><input type="checkbox" data-blocker-check data-blocker-key="PLAN-24" ${state==='validation'?'':'checked'}><span class="grow"><span class="key">PLAN-24</span> Add project permissions<div class="small muted">Sprint 1 · Core workflow${state==='existing-blockers'?' · Already linked':''}</div></span>${status('open')}</label><label class="dependency-row"><input type="checkbox" data-blocker-check data-blocker-key="PLAN-29"><span class="grow"><span class="key">PLAN-29</span> Add item query filters<div class="small muted">Sprint 1 · Core workflow</div></span>${status('in_progress')}</label></div><p class="small muted">At least one Blocked by link is required. Related, Parent and Child links do not count. Links and state will be saved together.</p></div>`,foot:link('Keep current state','08-item-detail','btn ghost')+btn(state==='existing-blockers'?'Move to Blocked':'Add blockers and move to Blocked',`data-confirm-block ${state==='validation'||state==='conflict'?'disabled':''}`,'primary')};
      case '34-blockers-resolved':return readyDialogSpec();
      case '35-cancel-blocker':return {title:'Cancel item and remove blocker links?',subtitle:'PLAN-24 · Add project permissions',wide:true,body:`<div class="stack">${state==='conflict'?error('The affected items changed. Refresh this impact preview and confirm the new list.'):''}<p>Cancelling <strong>PLAN-24</strong> will remove it as a blocker for these items. Continue?</p><div class="impact-list"><div class="dependency-row"><div class="grow"><strong>PLAN-18 · Build the sprint board</strong><div class="small muted">Currently Blocked · no blockers will remain</div></div><span class="outcome open">Moves to Open</span></div><div class="dependency-row"><div class="grow"><strong>PLAN-21 · Add attachment previews</strong><div class="small muted">${state==='remaining-done'?'PLAN-12 remains · Done':'PLAN-29 remains · In progress'}</div></div><span class="outcome">${state==='remaining-done'?'Remains Blocked · ready to resume':'Remains Blocked'}</span></div></div><div class="callout"><strong>PLAN-18 will move to Open automatically.</strong><p class="small">${state==='remaining-done'?'PLAN-21 keeps a completed blocker link and will ask about In progress on its next view.':'PLAN-21 still has an unresolved blocker, so it stays Blocked.'}</p></div><p class="small muted">Cancellation, link removal and automatic Open transitions happen together. Other link types and dependent items remain.</p>${state==='read-only'?'<p class="small danger-text">You do not have permission to cancel this item or update its dependents.</p>':''}</div>`,foot:link('Keep item unchanged','08-item-detail','btn ghost')+(state==='read-only'?'<button class="btn danger" disabled>Cancel item and remove links</button>':state==='conflict'?link('Refresh impact preview','35-cancel-blocker','btn primary'):link('Cancel item and remove links','08-item-detail','btn danger','blockers-removed','&item=PLAN-18'))};
      case '13-project-editor':return {title:state==='edit'?'Edit project':'Create project',body:`<div class="stack">${commonError}${field('Project name',state==='edit'?'Local Planner':'','text','',true)}${state==='edit'?'<div class="field"><span>Project key</span><div class="secret">PLAN</div><span class="hint">The key is fixed because it forms readable item keys.</span></div>':field('Project key','PLAN','text','Short uppercase key, such as PLAN. Item keys will look like PLAN-1.',true)}${textarea('Description',state==='edit'?'A lightweight home for projects, sprints and agent work.':'','Markdown supported. Describe the project and what it is for.')}</div>`,foot:footer(state==='edit'?'Save changes':'Create project','04-project-overview')};
      case '14-sprint-editor':return {title:state==='rename'?'Edit sprint':'Create sprint',subtitle:'Local Planner · PLAN',body:`<div class="stack">${commonError}${field('Name',state==='rename'?'Sprint 2 · Collaboration':'','text','',true)}${textarea('Description',state==='rename'?'':'','Optional. Markdown supported. Existing sprints have no description until edited.')}<p class="small muted">${state==='rename'?'Renaming keeps the sprint order and lifecycle unchanged.':'New sprints are added at the end of the order and are not started yet.'}</p></div>`,foot:footer(state==='rename'?'Save changes':'Create sprint','05-planning')};
      case '15-sprint-start':return {title:'Start sprint',subtitle:'Sprint 2 · Collaboration',body:state==='another-active'?`<div class="stack"><div class="callout warning">Sprint 1 · Core workflow is already active.</div><p>Each project can have one active sprint. Close the current sprint before starting another.</p></div>`:`<div class="stack"><p>This will become Local Planner's active sprint.</p><div class="quiet-band"><strong>2 items</strong><p class="small muted">Their states will stay the same.</p></div><p class="small muted">The start time is recorded automatically. There is no scheduled end date.</p></div>`,foot:footer(state==='another-active'?'Open active sprint':'Start sprint','07-sprint-board')};
      case '16-sprint-close':{
        const ready=state==='ready';
        return {title:'Close sprint',subtitle:'Sprint 1 · Core workflow',wide:true,body:`<div class="stack">${state==='conflict'?error('The sprint changed while you were reviewing it. Refresh this preview before closing.'):''}<div class="row"><span class="quiet-band"><strong>2</strong> Done</span><span class="quiet-band"><strong>1</strong> Cancelled</span><span class="quiet-band"><strong>${ready?'0':'5'}</strong> Unfinished</span></div><p>${ready?'All remaining work is Done or Cancelled. You can close this sprint.':'Move unfinished work to another sprint before closing. Done and Cancelled items will stay here.'}</p>${ready?'':`<div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Current state</th></tr></thead><tbody>${items.filter(i=>!['done','cancelled'].includes(i.state)).map(i=>`<tr><td><span class="key">${i.key}</span> &nbsp; ${e(i.title)}</td><td>${itemType(i.type)}</td><td>${status(i.state)}</td></tr>`).join('')}</tbody></table></div>${state==='no-destination'?'<div class="callout warning">There is no other sprint to move this work into. Create another sprint from Planning, then return here.</div>':select('Move unfinished work to',['Choose a sprint','Sprint 2 · Collaboration'],'Sprint 2 · Collaboration','States stay unchanged. Backlog is not available for this close-and-move action.')}`}<p class="small muted">Closing is final. ${ready?'The closure time will be recorded automatically.':'Moving the unfinished items and closing this sprint happen together.'}</p></div>`,foot:state==='no-destination'?footer('Open Planning','05-planning'):state==='conflict'?footer('Refresh preview','16-sprint-close'):footer(ready?'Close sprint':'Move 5 items and close','07-sprint-board','closed')};
      }
      case '17-item-create':return {title:'Create item',subtitle:'Local Planner · PLAN',wide:true,body:`<div class="stack">${commonError}<div class="two-fields">${select('Type',['Story','Task','Bug'],'Task')}${select('State',Object.values(names),state==='blocked'?'Blocked':'Open')}</div><div id="create-blockers" ${state==='blocked'?'':'hidden'} class="quiet-band stack"><h3>Blocked by <span class="small muted">Required for Blocked</span></h3><label class="check"><input type="checkbox" data-create-blocker="PLAN-24" ${state==='blocked'?'checked':''}>PLAN-24 · Add project permissions — Open</label><label class="check"><input type="checkbox" data-create-blocker="PLAN-29">PLAN-29 · Add item query filters — In progress</label><p class="small muted">Choose at least one blocker. Links and item are created together.</p></div>${field('Title','','text','',true)}${textarea('Description','','Markdown supported.')}<div class="two-fields">${select('Sprint',['Backlog','Sprint 1 · Core workflow','Sprint 2 · Collaboration'],state==='backlog'?'Backlog':'Sprint 1 · Core workflow')}${select('Assignee',['Unassigned','Taylor','agent-calm-otter-a31f'],'Unassigned')}${select('Priority',['None','Low','Medium','High','Urgent'],'None')}${select('Labels',['No labels','core','ui','files','access'],'No labels')}</div><p class="small muted">Only title and type are required. Items without a sprint go to Backlog.</p></div>`,foot:footer('Create and open','08-item-detail')};
      case '18-item-move':return {title:state==='reopen'?'Move and reopen item':state==='single'?'Move item':'Move items',subtitle:state==='single'||state==='reopen'?'PLAN-18 · Build the sprint board':'2 selected items · Local Planner',body:`<div class="stack">${commonError}${select('Destination',['Backlog','Sprint 1 · Core workflow','Sprint 2 · Collaboration'],'Sprint 2 · Collaboration')}${state==='reopen'?select('New state',['Open','In progress','Blocked'],'Open','Choose the new state explicitly; the item moves out of its closed sprint.'): '<div class="callout">Item states will stay the same. In progress stays In progress; Blocked stays Blocked.</div>'}<p class="small muted">Only nonclosed sprints in this project can receive items.</p></div>`,foot:footer(state==='reopen'?'Move and reopen':state==='single'?'Move item':'Move 2 items','05-planning')};
      case '19-item-link':{
        const dependency=['blocked-by','blocks'].includes(state);
        return {title:'Link item',subtitle:'PLAN-18 · Build the sprint board',body:`<div class="stack">${commonError}${select('This item is…',['Related to','Parent of','Child of','Blocked by','Blocks'],state==='parent'?'Child of':state==='blocked-by'?'Blocked by':state==='blocks'?'Blocks':'Related to')}${field('Find items',dependency?'permissions':'query filters','search','Search visible items in Local Planner by key or title.')}${state==='no-results'?'<p class="muted">No items match this search.</p>':dependency?`<div class="quiet-band"><label class="dependency-row"><input type="checkbox" checked><span class="grow"><span class="key">PLAN-24</span> Add project permissions<span class="small muted" style="display:block">Sprint 1 · Core workflow</span></span>${status('open')}</label><label class="dependency-row"><input type="checkbox"><span class="grow"><span class="key">PLAN-29</span> Add item query filters<span class="small muted" style="display:block">Sprint 1 · Core workflow</span></span>${status('in_progress')}</label></div><p class="small muted">${state==='blocks'?'Selected items will be blocked by this item.':'This item can be blocked by multiple selected items.'} Cancelled items cannot be blockers. Linking alone does not change state.</p>`:'<div class="quiet-band"><div class="row"><input type="radio" checked aria-label="Choose PLAN-29"><span class="key">PLAN-29</span><strong>Add item query filters</strong></div><div class="row" style="margin-top:9px">'+status('in_progress')+'<span class="small muted">Sprint 1 · Core workflow</span></div></div>'}<p class="small muted">Different sprints are allowed within this project. One parent; multiple blockers. Self-links and dependency cycles are rejected.</p></div>`,foot:state==='no-results'?`${link('Cancel','08-item-detail','btn ghost')}<button class="btn primary" disabled>Link item</button>`:footer(dependency?'Add links':'Link item','08-item-detail',dependency?'blocked':'default')};
      }
      case '20-label-manager':return {title:'Project labels',subtitle:'Local Planner · PLAN',body:`<div class="stack">${commonError}${state==='empty'?'<p class="muted">No labels yet. Create one to organize related work.</p>':`<div>${['access','core','docs','files','ui'].map(n=>`<div class="between" style="padding:11px 0;border-bottom:1px solid var(--line)"><span class="label">${n}</span>${readOnly()?'':`<div class="row">${btn('Rename',notice('Edit the label name in place. Names must be unique within this project.'),'ghost small')}${link('Delete','26-delete-confirmation','small danger-text','label')}</div>`}</div>`).join('')}</div>`}${readOnly()?'':`<div class="row">${field('New label','','text','',true)}${btn('Add label',notice('New label added to this preview only.'))}</div>`}</div>`,foot:link('Done','08-item-detail','btn primary')};
      case '21-attachment-preview':{
        let preview=state==='text'?'<pre class="text-preview" aria-label="Attachment text"># Sprint board acceptance notes\n\n- Show all five states.\n- Display item key and title on every card.\n- Keep Cancelled separate from Done.\n- Moving an item preserves its current state.\n\n## Keyboard use\nProvide a menu alternative for every drag action.</pre><p class="small muted">UTF-8 · 2 KB · Full preview. Larger text previews show a truncation notice.</p>':state==='unsupported'?empty('Preview is not available','You can still download this file.','','▤'):state==='error'?error('This preview could not be loaded. Try again or download the original.'):state==='loading'?'<div class="loading-panel" role="status">Loading preview…<div class="skeleton"></div><div class="skeleton short"></div></div>':'<div class="image-preview" role="img" aria-label="Example wireframe attachment showing a sidebar and work rows"><div class="sample-image"><aside></aside><main><strong class="small">Board layout reference</strong><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div><div class="skeleton"></div></main></div></div>';
        return {title:state==='text'?'acceptance-notes.md':state==='unsupported'?'project-export.zip':'board-reference.png',subtitle:state==='text'?'Text · 2 KB · Added by calm-otter':'Attachment · Added by Taylor',wide:true,body:`<div class="stack">${preview}</div>`,foot:btn('Download file',notice('Preview only. The real download is authorized using your attachment permissions.'))+link('Close','08-item-detail','btn primary')};
      }
      case '22-user-editor':{
        const agent=state==='agent';return {title:state==='edit'?'Edit user':'Create user',body:`<div class="stack">${commonError}${state==='edit'?'':`<div class="tabs">${link('Human','22-user-editor',`tab ${!agent?'active':''}`)}${link('Agent','22-user-editor',`tab ${agent?'active':''}`,'agent')}</div>`}${field('Display name',state==='edit'?'Morgan Lee':'','text','',!agent)}${agent?'<div class="callout">A unique username and UUID password will be generated when you create this agent. You will see the password once.</div>':`${state==='edit'?'':field('Username','','text','',true)}${state==='edit'?'':field('Initial password','','password','Use at least 12 characters.',true)}<label class="check"><input type="checkbox">Administrator <span class="small muted">Manages users and all projects.</span></label>`}<p class="small muted">${state==='edit'?'Existing project access is unchanged.':'New users have no project access until you grant it.'}</p></div>`,foot:footer(state==='edit'?'Save changes':agent?'Create agent':'Create human',agent?'24-agent-credentials':'09-users')};
      }
      case '23-user-detail':{
        const human=['human','last-admin'].includes(state),disabled=state==='disabled';return {title:human?'Taylor Ramos':'Calm Otter',subtitle:human?'Human · Administrator':'Agent · User',drawer:true,body:`<div class="stack"><div class="detail-prop"><label>Username</label><span class="mono small">${human?'tramos':'agent-calm-otter-a31f'}</span></div><div class="detail-prop"><label>Public user ID</label><span class="mono small" style="overflow-wrap:anywhere">10000000-0000-4000-8000-000000000001</span><p class="small muted" style="margin-top:6px">This identifies the account. It is not a password.</p></div><div><span class="${disabled?'muted':'success-text'}">${disabled?'Disabled':'Enabled'}</span><p class="small muted">${disabled?'This user cannot sign in. Authored history remains.':'Account is available for sign-in; project grants are separate.'}</p></div>${link('Edit details','22-user-editor','btn','edit')}<hr style="width:100%;border:0;border-top:1px solid var(--line)"><h2>Account actions</h2>${human?link('Reset password','25-password-editor','btn','admin-reset'):link('Rotate agent password','26-delete-confirmation','btn','rotate-agent')}${state==='last-admin'?'<div class="callout warning">This is the last enabled human administrator. Create or enable another administrator before disabling this account.</div><button class="btn" disabled>Disable account</button>':disabled?btn('Enable account',notice('Account enabled in this preview only.')):link('Disable account','26-delete-confirmation','btn danger','disable-user')}<p class="small muted">Disabling revokes sessions and tokens. User history is retained.</p></div>`,foot:link('Close','09-users','btn')};
      }
      case '24-agent-credentials':return {title:state==='rotated'?'Agent password rotated':'Agent created',subtitle:'Calm Otter · Agent',body:`<div class="stack"><div class="callout">Copy this password now. It will not be shown again.${state==='rotated'?' Previous sessions and tokens have been revoked.':''}</div><div class="field"><span>Username</span><div class="secret">agent-calm-otter-a31f</div>${btn('Copy username','data-copy="agent-calm-otter-a31f"','small')}</div><div class="field"><span>UUID password</span><div class="secret">00000000-0000-4000-8000-000000000000</div><span class="hint">Fictional example for design review.</span>${btn(state==='copied'?'Copied':'Copy UUID password','data-copy="00000000-0000-4000-8000-000000000000"','small')}</div><div class="permission-summary">This agent has no project access yet. Grant project permissions before using REST or MCP.</div><p class="small muted">Agent setup instructions will explain how to connect your local client.</p></div>`,foot:link('Manage permissions','10-project-permissions','btn')+link('Done','09-users','btn primary')};
      case '25-password-editor':return {title:state==='admin-reset'?'Reset human password':'Change password',subtitle:state==='admin-reset'?'Morgan Lee · morgan':'Taylor Ramos · tramos',body:`<div class="stack">${commonError}${state==='admin-reset'?'':field('Current password','','password','',true)}${field('New password','','password','Use at least 12 characters.',true)}${field('Confirm new password','','password','',true)}<p class="small muted">${state==='admin-reset'?"This signs out the user's existing sessions and revokes their API tokens.":'You will be signed out of existing sessions and asked to sign in again.'}</p></div>`,foot:footer(state==='admin-reset'?'Reset password':'Change password',state==='admin-reset'?'09-users':'02-login')};
      case '26-delete-confirmation':{
        if(['unlink-blocker','unlink-last-blocker','delete-blocker'].includes(state)){
          const last=state!=='unlink-blocker',deleting=state==='delete-blocker';
          return {title:deleting?'Delete item and remove blocker links?':'Remove blocker?',subtitle:'PLAN-24 · Add project permissions',body:`<div class="stack"><p>${deleting?'Deleting PLAN-24 also removes its Blocked by links from dependent items.':'Remove PLAN-24 as a blocker for PLAN-18 · Build the sprint board?'}</p><div class="callout"><strong>${last?"This is PLAN-18's last blocker.":'PLAN-29 will still block PLAN-18.'}</strong><p>${last?'PLAN-18 will move from Blocked to Open automatically.':'PLAN-18 will stay Blocked because another blocker remains.'}</p></div>${deleting?'<p class="small muted">The item and its comments/files are permanently removed. Dependent items remain. Review the full affected list before confirming.</p>':'<p class="small muted">Only this dependency link is removed. Both items remain.</p>'}</div>`,foot:link('Keep blocker','08-item-detail','btn ghost','blocked','&item=PLAN-18')+link(deleting?'Delete item and reopen dependent':last?'Remove blocker and move to Open':'Remove blocker','08-item-detail','btn danger',last?'blockers-removed':'blocked',`&item=PLAN-18${last?'':'&blocker_count=1'}`)};
        }
        const variants={sprint:['Delete sprint','Sprint 3 · Cleanup','Only an empty, not-started sprint can be deleted.','05-planning'],project:['Delete project','Home lab','This empty project will be permanently removed.','03-home'],comment:['Delete comment','Comment by Taylor','The comment will be permanently removed. Its audit record remains.','08-item-detail'],attachment:['Delete attachment','board-reference.png','The attachment and its stored file will be permanently removed.','08-item-detail'],label:['Delete label','ui','This label will be removed from every item in this project. The items will remain.','20-label-manager'],'disable-user':['Disable account','Calm Otter','Sign-in will be blocked and current sessions and tokens will be revoked. Authored history will remain.','09-users'],'rotate-agent':['Rotate password','Calm Otter','The existing UUID password, sessions and tokens will stop working. A new password will be shown once.','24-agent-credentials']};
        const d=variants[state]||['Delete item','PLAN-18 · Build the sprint board','The item, its comments and attachments will be permanently removed. Linked items will remain.','06-item-list'];
        return {title:state==='blocked'?'This action is unavailable':d[0],body:`<div class="stack"><strong>${e(d[1])}</strong>${state==='blocked'?'<div class="callout warning">This resource does not meet the deletion requirements, or you do not have all required delete permissions.</div><p class="muted">Check the resource details and required project permissions before continuing.</p>':`<p>${e(d[2])}</p><p class="small muted">${state==='disable-user'?'You can enable this account later.':state==='rotate-agent'?'Copy the replacement password before closing the next dialog.':'This cannot be undone.'}</p>`}</div>`,foot:state==='blocked'?link('Back to item','08-item-detail','btn primary'):footer(d[0],d[3],state==='rotate-agent'?'rotated':'default',true)};
      }
      case '27-edit-conflict':return {title:state==='deleted'?'This item is no longer available':'This changed while you were editing',wide:true,body:`<div class="stack"><p>${state==='deleted'?'Your unsaved text is still here. The saved item was deleted or you no longer have access.':'Another user or agent saved a newer version. Review it before reapplying your changes.'}</p><div class="diff-grid"><div class="diff-panel"><h3>Your draft</h3><p>${state==='permissions'?'Items: View, Create, Update':'Priority: High'}</p><p class="small muted" style="margin-top:9px">Not saved</p></div><div class="diff-panel"><h3>Latest saved</h3><p>${state==='deleted'?'Unavailable':state==='permissions'?'Items: View only':'Priority: Urgent'}</p><p class="small muted" style="margin-top:9px">${state==='deleted'?'No resource details are shown.':'Updated by calm-otter · just now'}</p></div></div>${btn('Copy draft','data-copy="Priority: High"','small')}<p class="small muted">Your draft will never overwrite a newer version automatically.</p></div>`,foot:state==='deleted'?link('Back to Home','03-home','btn primary'):link('Load latest',state==='permissions'?'10-project-permissions':'08-item-detail','btn')+link('Keep editing',state==='permissions'?'10-project-permissions':'08-item-detail','btn primary',state==='permissions'?'dirty':'editing')};
      case '31-session-expired':return {title:'Your session has expired',body:`<div class="stack"><p>Sign in again to continue. Your unsaved work has not been submitted.</p>${state==='with-draft'?`<div class="diff-panel"><h3>Your unsaved draft</h3><p style="margin-top:9px">Add a keyboard alternative for card movement.</p></div>${btn('Copy draft','data-copy="Add a keyboard alternative for card movement."')}`:''}</div>`,foot:link('Sign in','02-login','btn primary')};
      case '32-unsaved-changes':return {title:'Leave without saving?',body:`<div class="stack"><p>Your changes to ${state==='permissions'?'project permissions':'the item description'} have not been saved.</p><p class="muted">Keep editing, or discard this draft and leave. The saved ${state==='permissions'?'permissions':'item'} will remain unchanged.</p></div>`,foot:link('Discard changes','03-home','btn')+link('Keep editing',state==='permissions'?'10-project-permissions':'08-item-detail','btn primary',state==='permissions'?'dirty':'editing')};
      default:return {title:screen.name,body:'',foot:link('Close',screen.parent||'03-home','btn')};
    }
  }
  function system(){
    if(id==='28-access-denied')return empty('You do not have access to this page','Your current permissions do not allow this action.',link('Back to Home','03-home','btn primary')+btn('Back','data-back'),'⚿');
    if(id==='29-not-found')return empty(state==='deleted'?'This item was deleted':'Page not found',state==='deleted'?'The item you were viewing is no longer available.':'This page is unavailable or you do not have access to it.',link('Back to Home','03-home','btn primary')+btn('Back','data-back'),'□');
    return pageHead('Local Planner',state==='cached'?'Last updated 4 minutes ago':'')+`<div class="callout warning" role="alert"><div class="between"><div><strong>${state==='busy'?'The app is busy. Try again shortly.':'Could not connect to your local workspace.'}</strong><p class="small muted" style="margin-top:5px">${state==='cached'?'Showing previously loaded information. New changes have not been saved.':'Check that the local app is running, then retry. Your draft has not been cleared.'}</p></div>${btn('Retry','data-retry','primary')}</div></div>${state==='cached'?section('Previously loaded items',table(items.slice(0,3))):empty('Your workspace is temporarily unavailable','You can retry without losing your unsaved text.','', '↻')}`;
  }
  function loading(){return pageHead(screen.name,'Loading your workspace…')+`<div class="loading-panel" role="status" aria-label="Loading"><div class="skeleton short"></div><div class="skeleton"></div>${Array.from({length:6},()=>'<div class="skeleton-row"><div class="skeleton"></div><div class="skeleton short"></div></div>').join('')}</div>`;}
  const renderers={'03-home':home,'04-project-overview':project,'05-planning':planning,'06-item-list':list,'07-sprint-board':board,'08-item-detail':item,'09-users':users,'10-project-permissions':permissions,'11-appearance':appearance,'12-account-security':account};
  const activeNames={'03-home':'Home','04-project-overview':'Project overview','05-planning':'Planning','06-item-list':'List','07-sprint-board':'Sprint','08-item-detail':'Items','09-users':'Users','10-project-permissions':'Permissions','11-appearance':'Appearance','12-account-security':'Account'};
  function reviewbar(){const index=catalogue.indexOf(screen);return `<aside class="reviewbar" aria-label="Design review controls"><div><a href="../index.html#${screen.id}">← All screens</a> <span class="review-label">&nbsp; ${screen.name}</span> <span class="preview-only">· Review draft · Fictional data</span></div><div class="row"><label>State <select data-state-select>${screen.states.map(s=>`<option value="${s}" ${s===state?'selected':''}>${s==='default'?'Default':s.replaceAll('-',' ')}</option>`).join('')}</select></label><label>Mode <select data-theme-select>${['light','dark','system'].map(s=>`<option ${s===mode?'selected':''}>${s}</option>`).join('')}</select></label><label>Accent <select data-accent-select>${Object.keys(colors).map(s=>`<option ${s===accent?'selected':''}>${s}</option>`).join('')}</select></label>${index>0?link('←',catalogue[index-1].id,'btn small'):''}${index<catalogue.length-1?link('→',catalogue[index+1].id,'btn small'):''}</div></aside>`;}
  function render(){
    fieldCount=0;
    applyTheme();
    document.title=`${screen.name} · Local Planner design`;
    document.body.classList.toggle('embedded',params.has('embed'));
    let body;
    if(id==='01-setup'||id==='02-login')body=auth(id==='01-setup');
    else if(renderers[id])body=shell(state==='loading'?loading():renderers[id](),activeNames[id]);
    else if(['28-access-denied','29-not-found','30-service-unavailable'].includes(id))body=shell(system());
    else {
      const spec=dialogContent();
      const parent=screen.parent||'03-home';
      const parentState=state;
      state=id==='34-blockers-resolved'?(parentState==='read-only'?'blockers-ready-readonly':'blockers-ready'):'default';
      const background=id==='31-session-expired'?shell('<div aria-hidden="true" class="loading-panel"><div class="skeleton"></div><div class="skeleton short"></div></div>','Home',true):shell((renderers[parent]||home)(),activeNames[parent]||'Home',true);
      state=parentState;
      body=background+`<div class="overlay ${spec.drawer?'drawer-overlay':''}"><section class="modal ${spec.wide?'wide':''} ${spec.drawer?'drawer':''}" ${!spec.wide&&!spec.drawer?`style="width:min(100%,${({'13-project-editor':520,'14-sprint-editor':440,'15-sprint-start':480,'17-item-create':650})[id]||540}px)"`:''} role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><div><h1 id="dialog-title">${spec.title}</h1>${spec.subtitle?`<p class="modal-subtitle">${spec.subtitle}</p>`:''}</div>${id==='31-session-expired'?'':`<a href="${path(parent)}" class="btn ghost icon-btn" aria-label="Close dialog">×</a>`}</div><div class="modal-content">${spec.body}</div><footer class="modal-footer">${spec.foot}</footer></section></div>`;
    }
    document.getElementById('preview-root').innerHTML=reviewbar()+body;
    bind();
    if(id==='08-item-detail'&&state==='blockers-ready'&&!readinessPromptDismissed)showReadyDialog();
    const focus=document.querySelector('.modal input:not([disabled]), .modal button:not([disabled]), .modal a');
    if(focus)focus.focus({preventScroll:true});
    parent.postMessage({type:'design-screen',id,state,theme:mode,accent},'*');
  }
  function toast(message){
    document.querySelector('.toast')?.remove();
    const t=document.createElement('div');t.className='toast';t.role='status';t.textContent=message;document.body.append(t);
    clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),4200);
  }
  function changeQuery(){const q=new URLSearchParams(location.search);q.set('state',state);q.set('theme',mode);q.set('accent',accent);history.replaceState(null,'',`${location.pathname}?${q}`);}
  function bind(){
    document.querySelector('[data-state-select]')?.addEventListener('change',ev=>{state=ev.target.value;readinessPromptDismissed=false;changeQuery();render();});
    document.querySelector('[data-theme-select]')?.addEventListener('change',ev=>{mode=ev.target.value;changeQuery();render();});
    document.querySelector('[data-accent-select]')?.addEventListener('change',ev=>{accent=ev.target.value;changeQuery();render();});
    document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;changeQuery();render();}));
    document.querySelectorAll('[data-accent]').forEach(b=>b.addEventListener('click',()=>{accent=b.dataset.accent;changeQuery();render();}));
    document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.addEventListener('click',()=>{mode=document.documentElement.dataset.theme==='dark'?'light':'dark';changeQuery();render();}));
    document.querySelector('[data-show-ready]')?.addEventListener('click',showReadyDialog);
    document.querySelector('[data-confirm-block]')?.addEventListener('click',()=>{const selected=[...document.querySelectorAll('[data-blocker-check]:checked')].map(c=>c.dataset.blockerKey);if(selected.length)location.href=path('08-item-detail','blocked','&item=PLAN-18&blocker_keys='+selected.join(','));});
    document.querySelectorAll('[data-blocker-check]').forEach(c=>c.addEventListener('change',()=>{const action=document.querySelector('[data-confirm-block]');if(action)action.disabled=!document.querySelector('[data-blocker-check]:checked');}));
    if(id==='17-item-create')document.querySelector('[data-field-label="State"]')?.addEventListener('change',ev=>{document.getElementById('create-blockers').hidden=ev.target.value!=='Blocked';});
    if(id==='17-item-create')document.querySelector('.modal-footer a.primary')?.addEventListener('click',ev=>{if(document.querySelector('[data-field-label="State"]').value==='Blocked'){ev.preventDefault();const keys=[...document.querySelectorAll('[data-create-blocker]:checked')].map(c=>c.dataset.createBlocker);if(!keys.length){toast('Choose at least one Blocked by item before creating a Blocked item.');return;}location.href=path('08-item-detail','blocked','&item=PLAN-18&blocker_keys='+keys.join(','));}});

    if(id==='19-item-link')document.querySelector('[data-field-label="This item is…"]')?.addEventListener('change',ev=>{const variant=ev.target.value==='Blocked by'?'blocked-by':ev.target.value==='Blocks'?'blocks':ev.target.value==='Child of'?'parent':'default';location.href=path('19-item-link',variant);});

    document.querySelectorAll('[data-dismiss-ready]').forEach(b=>b.addEventListener('click',dismissReady));
    document.querySelector('[data-resume-preview]')?.addEventListener('click',resumePreview);
    document.querySelectorAll('[data-notice]').forEach(b=>b.addEventListener('click',()=>toast(b.dataset.notice)));
    document.querySelector('[data-item-menu]')?.addEventListener('click',ev=>{
      document.querySelector('.item-menu')?.remove();
      const menu=document.createElement('div');menu.className='item-menu';menu.setAttribute('role','group');menu.setAttribute('aria-label','Item actions');menu.innerHTML=link('Move item','18-item-move','btn ghost full','single')+link('Delete item','26-delete-confirmation','btn ghost danger-text full');ev.currentTarget.parentElement.style.position='relative';ev.currentTarget.parentElement.append(menu);menu.querySelector('a')?.focus();
    });
    document.querySelectorAll('[data-property]').forEach(b=>b.addEventListener('click',()=>{
      document.querySelector('.property-picker')?.remove();
      const choices={State:Object.values(names),Type:['Story','Task','Bug'],Assignee:['Unassigned','Taylor','agent-calm-otter-a31f'],Priority:['None','Low','Medium','High','Urgent']};
      const picker=document.createElement('div');picker.className='property-picker';picker.setAttribute('role','group');picker.setAttribute('aria-label',`Choose ${b.dataset.property.toLowerCase()}`);
      for(const value of choices[b.dataset.property]||[]){const option=document.createElement('button');option.className='btn ghost full';option.textContent=value;option.addEventListener('click',()=>{if(b.dataset.property==='State'&&value==='Blocked'){location.href=path('33-block-item');return;}if(b.dataset.property==='State'&&value==='Cancelled'){location.href=path('35-cancel-blocker');return;}b.textContent=value+' ⌄';picker.remove();b.focus();toast('Property changed in this preview only.');});picker.append(option);}
      b.parentElement.append(picker);picker.querySelector('button')?.focus();
    }));
    document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied';toast('Example text copied.');}catch{toast('Copy is unavailable in this browser context. Select the example text manually.');}}));
    document.querySelector('[data-menu]')?.addEventListener('click',()=>document.querySelector('.app').classList.toggle('menu-open'));
    document.querySelector('[data-project-picker]')?.addEventListener('click',()=>toast('Preview project: Local Planner. Other projects use the same screen layout.'));
    document.querySelector('[data-show-password]')?.addEventListener('change',ev=>{document.querySelectorAll('input[type=password],input[data-password-visible]').forEach(i=>{i.type=ev.target.checked?'text':'password';i.dataset.passwordVisible='1';});});
    document.querySelector('[data-auth-form]')?.addEventListener('submit',ev=>{ev.preventDefault();location.href=path('03-home');});
    document.querySelectorAll('[data-save-preview]').forEach(b=>b.addEventListener('click',()=>toast('Preview only — no application data was saved.')));
    document.querySelector('[data-save-permissions]')?.addEventListener('click',()=>toast('Permission design preview only — no real access changed.'));
    document.querySelector('[data-back]')?.addEventListener('click',()=>location.href=path('03-home'));
    document.querySelector('[data-retry]')?.addEventListener('click',()=>toast('Retry preview — your local draft stays available.'));
    document.querySelectorAll('.permission-table input').forEach(input=>input.addEventListener('change',()=>{const row=input.closest('tr');const checks=[...row.querySelectorAll('input')];if(input!==checks[0]&&input.checked)checks[0].checked=true;if(input===checks[0]&&!input.checked)checks.slice(1).forEach(x=>x.checked=false);toast('Unsaved permission draft. Save to apply in the implemented app.');}));
  }
  window.addEventListener('message',event=>{if(event.source!==window.parent)return;const d=event.data;if(d?.type!=='design-settings')return;mode=d.theme||mode;accent=d.accent||accent;if(d.state&&screen.states.includes(d.state)){if(state!==d.state)readinessPromptDismissed=false;state=d.state;}changeQuery();render();});
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(mode==='system')applyTheme();});
  document.addEventListener('keydown',event=>{
    if(event.key==='Escape'){const menu=document.querySelector('.property-picker,.item-menu');if(menu){menu.remove();return;}}
    const modal=document.querySelector('.modal');if(!modal)return;
    if(event.key==='Escape'&&(document.querySelector('.readiness-overlay')||id==='34-blockers-resolved')){dismissReady();return;}
    if(event.key==='Escape'&&id!=='31-session-expired'){location.href=path(screen.parent||'03-home');return;}
    if(event.key==='Tab'){const focusable=[...modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')];const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
  });
  if(screen){if(id==='11-appearance'&&state==='dark')mode='dark';if(id==='11-appearance'&&state==='system')mode='system';render();}
})();
